from bisect import bisect_left, bisect_right

def rangeFrequency(nums, queries):
    positions = {}
    for i, v in enumerate(nums):
        positions.setdefault(v, []).append(i)
    out = []
    for l, r, v in queries:
        lst = positions.get(v)
        if not lst:
            out.append(0)
        else:
            out.append(bisect_right(lst, r) - bisect_left(lst, l))
    return out
